INSERT INTO public.periods (id,wikidata_id,label_fr,label_en,description_fr,description_en,start_date,end_date,start_years_bp,end_years_bp,non_thematic,wikipedia_title_fr,wikipedia_title_en) VALUES
('ff08c0f5-f954-4cc5-ab72-b0b715d16e6a',NULL,'Révolutions et Empire napoléonien','Revolutions and the Napoleonic Empire','La Révolution française, l’indépendance d’Haïti et les guerres napoléoniennes bouleversent l’ordre politique et social.','The French Revolution, Haitian independence and the Napoleonic wars transform the political and social order.','1789-05-05','1815-06-22',237.51266255989,211.385352498289,true,NULL,NULL),
('4df111b2-48ec-4fd7-99a1-a14a7adf8da5',NULL,'Industrialisation et empires coloniaux','Industrialisation and colonial empires','L’industrie et les transports transforment les sociétés tandis que les révolutions politiques et l’expansion coloniale redessinent les rapports de puissance.','Industry and transport transform societies while political revolutions and colonial expansion reshape relations between powers.','1815-06-22','1914-07-28',211.385352498289,112.288843258042,true,NULL,NULL),
('8ff93b0d-e095-486a-a5c8-601286fe5268',NULL,'Guerres mondiales et crises','World wars and crises','Les deux guerres mondiales, la révolution russe, les totalitarismes et la crise économique bouleversent les sociétés et l’ordre international.','Two world wars, the Russian Revolution, totalitarian regimes and economic crisis transform societies and the international order.','1914-07-28','1945-09-02',112.288843258042,81.1895961670089,true,NULL,NULL),
('77ac92f0-9470-4de7-a93d-9c2e0a463c61',NULL,'Guerre froide et décolonisations','Cold War and decolonisation','La rivalité entre États-Unis et URSS, les indépendances, les droits civiques et la conquête spatiale marquent un monde profondément transformé par la guerre.','US–Soviet rivalry, independence movements, civil rights and space exploration shape a world profoundly transformed by war.','1945-09-02','1991-12-26',81.1895961670089,34.8761122518823,true,NULL,NULL),
('2eb62b42-b829-4f0b-a458-07b69f24f013',NULL,'Mondialisation et défis contemporains','Globalisation and contemporary challenges','Après la disparition de l’URSS, les réseaux numériques, les crises économiques, les conflits et les enjeux climatiques et sanitaires transforment les relations mondiales.','After the Soviet Union’s dissolution, digital networks, economic crises, conflicts and climate and health challenges reshape global relations.','1991-12-26','TODAY',34.8761122518823,0,true,NULL,NULL);
